const prepare = function prepareFeedback({ values }) {
  const questions = ['What went great?', 'How can we improve?', 'What is the chance of recommending our event?'];
  if (!Array.isArray(values)) throw new Error('Feedback values must be an array.');
  if (!values.length) return { count: 0, text: '' };
  const headers = values[0];
  if (!Array.isArray(headers) || questions.some((question) => !headers.includes(question))) throw new Error('Feedback sheet must contain the three configured question headers.');
  for (const question of questions) if (headers.filter((header) => header === question).length !== 1) throw new Error('Duplicate feedback header: ' + question);
  const rows = values.slice(1).filter((row) => Array.isArray(row) && row.some((value) => value !== null && value !== ''));
  const text = questions.map((question, index) => `${index + 1}. ${question}: ${rows.map((row) => String(row[headers.indexOf(question)] ?? '')).join(' | ')}`).join('\n');
  return { count: rows.length, text };
}

const headers = ["What went great?","How can we improve?","What is the chance of recommending our event?"];
const values = [headers, ...$input.all().map(item => headers.map(header => item.json[header] ?? ''))];
const report = prepare({values});
return report.count ? [{json: {feedback: report.text}}] : [];
